from __future__ import annotations

import sqlite3
from typing import Literal

from fastapi import APIRouter, Depends, Query, Response, status
from pydantic import BaseModel, Field

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoOut(BaseModel):
 id: int
 title: str
 done: bool
 created_at: str
 updated_at: str

class TodoCreate(BaseModel):
 title: str = Field(min_length=1, max_length=200)

class TodoPatch(BaseModel):
 title: str | None = Field(default=None, min_length=1, max_length=200)
 done: bool | None = None

def _todo_row_to_out(row: sqlite3.Row) -> TodoOut:
 return TodoOut(
  id=row["id"],
  title=row["title"],
  done=bool(row["done"]),
  created_at=row["created_at"],
  updated_at=row["updated_at"],
 )

@router.get("", response_model=dict, summary="List todos")
def list_todos(
 done: Literal["true", "false"] | None = Query(default=None, description="Filter by done status"),
 page: PageParams = Depends(page_params),
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> dict:
 sql = "SELECT * FROM todos WHERE user_id = ?"
 params: list = [user.id]
 if done is not None:
  sql += " AND done = ?"
  params.append(1 if done == "true" else 0)
 sql += " ORDER BY created_at DESC"
 total = conn.execute(f"SELECT COUNT(*) FROM ({sql})", params).fetchone()[0]
 sql += " LIMIT ? OFFSET ?"
 params.extend([page.limit, page.offset])
 rows = conn.execute(sql, params).fetchall()
 items = [_todo_row_to_out(r) for r in rows]
 return paginate(items, total, page)

@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED, summary="Create a todo")
def create_todo(
 data: TodoCreate,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 now = utc_now()
 cur = conn.execute(
  "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
  (user.id, data.title.strip(), now, now),
 )
 row = conn.execute("SELECT * FROM todos WHERE id = ?", (cur.lastrowid,)).fetchone()
 return _todo_row_to_out(row)

@router.get("/{todo_id}", response_model=TodoOut, summary="Get a todo")
def get_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id)).fetchone()
 if not row:
  raise not_found("todo_not_found", "Todo not found.")
 return _todo_row_to_out(row)

@router.patch("/{todo_id}", response_model=TodoOut, summary="Update a todo")
def update_todo(
 todo_id: int,
 data: TodoPatch,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id)).fetchone()
 if not row:
  raise not_found("todo_not_found", "Todo not found.")
 updates = []
 params = []
 if data.title is not None:
  updates.append("title = ?")
  params.append(data.title.strip())
 if data.done is not None:
  updates.append("done = ?")
  params.append(1 if data.done else 0)
 if not updates:
  return _todo_row_to_out(row)
 updates.append("updated_at = ?")
 params.append(utc_now())
 params.extend([todo_id, user.id])
 conn.execute(f"UPDATE todos SET {', '.join(updates)} WHERE id = ? AND user_id = ?", params)
 row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id)).fetchone()
 return _todo_row_to_out(row)

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> Response:
 cur = conn.execute("DELETE FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id))
 if cur.rowcount == 0:
  raise not_found("todo_not_found", "Todo not found.")
 return Response(status_code=status.HTTP_204_NO_CONTENT)
