import { apiFetch, ApiError, loadToken, clearToken, TOKEN_KEY } from "./api.js";
import { showMessage, el, clear, formatTime, whileBusy, formValues } from "./ui.js";

if (!loadToken()) {
location.href = "login.html";
}

const usernameEl = document.getElementById("username");
const signoutBtn = document.getElementById("signout");
const addForm = document.getElementById("add-form");
const listEl = document.getElementById("list");
const filterBtns = document.querySelectorAll("#filter button");
const prevBtn = document.getElementById("prev");
const nextBtn = document.getElementById("next");
const pageInfo = document.getElementById("page-info");

let currentFilter = "all";
let offset = 0;
let limit = 20;
let total = 0;

signoutBtn.addEventListener("click", () => {
clearToken();
location.href = "login.html";
});

async function loadUser() {
try {
const me = await apiFetch("/api/auth/me");
usernameEl.textContent = me.username;
} catch (err) {
if (err instanceof ApiError && err.status === 401) {
clearToken();
location.href = "login.html";
} else {
showMessage("Failed to load user", "error");
}
}
}

function setActiveFilter(btn) {
filterBtns.forEach(b => b.classList.toggle("active", b === btn));
currentFilter = btn.dataset.filter;
offset = 0;
loadTodos();
}

filterBtns.forEach(btn => btn.addEventListener("click", () => setActiveFilter(btn)));

async function loadTodos() {
try {
const query = new URLSearchParams({ limit, offset });
if (currentFilter !== "all") query.set("done", currentFilter === "done" ? "true" : "false");
const data = await apiFetch(`/api/todos?${query}`);
total = data.total;
renderTodos(data.items);
updatePager();
} catch (err) {
if (err instanceof ApiError) showMessage(err.message, "error");
else showMessage("Network error", "error");
}
}

function renderTodos(items) {
clear(listEl);
if (items.length === 0) {
listEl.appendChild(el("li", { class: "list-item muted" }, "No todos yet."));
return;
}
for (const todo of items) {
const li = el("li", { class: "list-item" + (todo.done ? " done" : ""), "data-id": todo.id });
const checkbox = el("input", { type: "checkbox", checked: todo.done, "aria-label": "Mark as done" });
checkbox.addEventListener("change", () => toggleDone(todo.id, checkbox.checked));
const titleSpan = el("span", { class: "grow title" }, todo.title);
titleSpan.addEventListener("dblclick", () => renameTodo(todo.id, titleSpan));
const actions = el("div", { style: "display:flex; gap:4px" });
const renameBtn = el("button", { class: "secondary", title: "Rename" }, "✎");
renameBtn.addEventListener("click", () => renameTodo(todo.id, titleSpan));
const deleteBtn = el("button", { class: "danger", title: "Delete" }, "🗑");
deleteBtn.addEventListener("click", () => deleteTodo(todo.id));
actions.append(renameBtn, deleteBtn);
li.append(checkbox, titleSpan, actions);
listEl.appendChild(li);
}
}

async function toggleDone(id, done) {
try {
await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { done } });
showMessage(done ? "Marked as done" : "Marked as open", "success");
} catch (err) {
if (err instanceof ApiError) showMessage(err.message, "error");
else showMessage("Network error", "error");
loadTodos();
}
}

function renameTodo(id, titleSpan) {
const current = titleSpan.textContent;
const input = el("input", { type: "text", value: current, style: "flex:1" });
const save = () => {
const newTitle = input.value.trim();
if (newTitle && newTitle !== current) {
updateTitle(id, newTitle);
} else {
titleSpan.textContent = current;
}
};
input.addEventListener("blur", save);
input.addEventListener("keydown", (e) => { if (e.key === "Enter") save(); });
titleSpan.replaceWith(input);
input.focus();
}

async function updateTitle(id, title) {
try {
await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { title } });
showMessage("Renamed", "success");
} catch (err) {
if (err instanceof ApiError) showMessage(err.message, "error");
else showMessage("Network error", "error");
}
loadTodos();
}

async function deleteTodo(id) {
if (!confirm("Delete this todo?")) return;
try {
await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
showMessage("Deleted", "success");
loadTodos();
} catch (err) {
if (err instanceof ApiError) showMessage(err.message, "error");
else showMessage("Network error", "error");
}
}

addForm.addEventListener("submit", async (e) => {
e.preventDefault();
await whileBusy(addForm, async () => {
const data = formValues(addForm);
try {
await apiFetch("/api/todos", { method: "POST", body: { title: data.title } });
addForm.reset();
showMessage("Added", "success");
loadTodos();
} catch (err) {
if (err instanceof ApiError) showMessage(err.message, "error");
else showMessage("Network error", "error");
}
});
});

prevBtn.addEventListener("click", () => {
if (offset > 0) {
offset -= limit;
loadTodos();
}
});

nextBtn.addEventListener("click", () => {
if (offset + limit < total) {
offset += limit;
loadTodos();
}
});

function updatePager() {
prevBtn.disabled = offset === 0;
nextBtn.disabled = offset + limit >= total;
const start = total === 0 ? 0 : offset + 1;
const end = Math.min(offset + limit, total);
pageInfo.textContent = `${start}–${end} of ${total}`;
}

loadUser();
loadTodos();
